{
  "title": "夜探客栈",
  "scene": "夜色如墨，你悄悄来到小镇边缘的『醉仙楼』。这座客栈外表破旧，却在江湖中颇有名气，据说隐藏着不少秘密。正门紧闭，上方悬挂的灯笼随风摇曳，微弱的光线勉强照亮了前方。侧墙有一处不起眼的通风口，似乎可以钻入。后院则传来轻微的交谈声，似乎有人在密谋。据说客栈内藏有一本记载着各大门派轻功秘籍的古书，你此行的目的便是找到它。但此地戒备森严，稍有不慎便可能陷入险境。你必须选择一个进入的方式。",
  "goal": "潜入客栈，找到并带走轻功秘籍",
  "clue": "通风口处有一张被风吹落的纸条，上面写着『后院有暗道』。",
  "choices": [
    {
      "id": "A",
      "text": "从正门硬闯",
      "outcome": "你用力推开了正门，但瞬间触发了机关，引来大批守卫。尽管你奋力抵抗，最终还是被擒，失去了此次行动的机会，并且声望受损。",
      "result": "fail",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "钻入通风口",
      "outcome": "你发现通风口处有一张纸条，上面提到了后院的暗道。你决定利用这条线索尝试潜入，最终成功找到了轻功秘籍并安全带走。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "偷听后院的密谋",
      "outcome": "你小心翼翼地接近后院，却发现那里的人正在讨论如何对付你。你被发现并遭到伏击，虽然侥幸逃脱，但未能找到轻功秘籍，且身受重伤。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
